import{_ as e,c as t,o as p,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"易纂言卷九","description":"易纂言 - 易纂言卷九","frontmatter":{"title":"易纂言卷九","description":"易纂言 - 易纂言卷九"},"headers":[],"relativePath":"zh/classics/zuanyan/010.md","filePath":"zh/classics/zuanyan/010.md"}'),n={name:"zh/classics/zuanyan/010.md"};function r(c,a,_,i,o,l){return p(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="易纂言卷九" tabindex="-1">易纂言卷九 <a class="header-anchor" href="#易纂言卷九" aria-label="Permalink to “易纂言卷九”">​</a></h1><p>钦定四库全书</p><p>元吴澄撰</p><p>文言传 文言者，彖、爻之辞也。案：系辞传曰：其辞文，谓彖、爻之辞，文其言而不质，直言之也。此篇天子所以释文王、周公之文言，故曰文言传。繋辞传者，统论圣人系辞之意也。文言传者，详释经中文言之辞也。</p><p>「元」者，善之长也；「亨」者，嘉之会也；「利」者，义之和也；贞者，事之干也。君子体仁足以长人；嘉会足以合礼；利物足以和义；贞固足以干事。君子行此四德者，故曰：「乾：元亨利贞。」 此一节释乾彖辞。彖辞本意谓元者亨而利于贞，元言其人，贞言其事，亨利言其占也。夫子于此释「元亨利贞」四字，而分为四德，后人因之以配春夏秋冬，以配仁义礼智，皆推广而言也。「元」如人首，在众体之上，于时为春，先乎四时，于人为仁，统乎五常，故为众善之长。「亨」如享礼，萃诸物之珍，于时为夏，万物茂盛，于人为礼，多仪备具，故为嘉美之会。「利」如刀刃之利，于时为秋，凡物各遂，不相妨害；于人为义，凡事得宜，无所乖戾，故为义之和。「贞」如木身之桢，于时为冬，物皆归复而有藏；于人为智，物皆辨察而有立，故为事之干。干者，木之枝叶所依以立。智之能立事，亦犹是也。项氏曰：「在事之初为善，善之众盛为嘉，众得其盛为义，义所成立为事，一理而四名之。」澄案：春秋左氏传亦载此言，但「善」字作「体」字，彼释人首之「元」，此则假借「元」字以名天德，故改「体」为「善」。盖自昔有此训诂，夫子述之尔。「君子」谓用易之人，法乾之「元」而以仁为体，则善之长在，已可以为人之长矣。「合礼」之「合」如合乐之合，谓会聚备具也。法乾之「亨」而嘉美会聚，则美物众盛，可以备具乎礼矣。法乾之利而宜利于应物，则可以不乖乎义矣。法乾之贞而智之正，如木桢之固，则可以为事之干矣。春秋传无「君子」字，「嘉会」作「嘉德」，此加「君子」字以表用。易者改「德」为「会」，乃与上文协，而得「亨」字之意。君子如是，则为能行此四德，而亦如乾之「元亨利贞」也。 初九曰「潜龙勿用」，何谓也？龙德而隐者也。不易乎世，不成乎名，遁世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。 此一节释乾初九爻辞。「龙德」，喻圣人之德。「隐」，释「潜」也。「易」，变移也。成，完全。周，足也。「不易乎世」者，有守于中，不随时俗而变移也。「不成乎名」者，无愿于外，不使声实之周足也。「遁世」，身隐而不见也。不见是，人不以之为是也。不随世而易，则不肯以身殉世，故虽隐遁于世而亦无闷。不使其名之成，则不肯以身殉名，故虽不见是于人而亦无闷。「乐则行之」，释上文「无闷」二句。「忧则违之」，释上文「不易」、「不成」二句。乐者，谓无闷也。行之，谓为之也。忧者，谓非其所乐也。违之，谓不为也。不求见于世、不求知于人者，此其所乐也，则为之。易乎世、成乎名者，此非其所乐也，则不为。确，坚貌。拔，如拔木之拔，谓其志坚确，不可转徙而他也。 九二曰：「见龙在田，利见大人。」何谓也？龙，德而正中者也。庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。 此一节释乾九二爻辞。朱子曰：「正中，不潜而未跃之时也。常言亦信，常行亦谨，盛德之至也。闲邪存其诚，无𭣧亦保之意。」澄谓：中正释见而在田也。以下卦言，初在下，三在上，二在当其中也。庸言以下，释大人闲邪，外物不能入也。应物而中不动，故实心不为物所引，而常存于中也。善世以下，利见之意。善于一世而不自骄，德之及人者博，而人皆化。盖虽居下位而德已著，故世之人利于见之也。 九三曰：「君子终日乾乾，夕惕若，厉，无咎。」何谓也？君子进德修业。忠信，所以进德也；修辞立其诚，所以居业也。知至至之，可与几也。知终终之，可与存义也。是故居上位而不骄，在下位而不忧，故乾乾因其时而惕，虽危无咎矣。 此一节释乾九三爻辞。九二言大人之德，九三言君子之学。「进德修业」，释「终日乾乾，夕惕若」。「君子终日乾乾」，至夕而犹「惕若」者，何哉？以进其德，修其业也。「进」，谓日新不已。「修」，谓徧举无遗。「忠信」以下，详言进修之目。「忠信」者，尽心于中，而达乎在外之信也。心常实，则德无时不进矣。「修辞立其诚」者，修辞于外，而固守其在中之诚也。事皆实，则业无一不修矣。「居」，犹「居货」之「居」，虽未徧为，而已藏积于此也。「知至」「知终」，知也。「至之终之」，行也。「可与」，犹论语之「可与共」。学先知所至，而行以至之，则自其动之微而趋于善，故曰「可与几也」。「几」者，进德之端也。既知所终，而行以终之，则制事之宜皆存于此，故曰「可与存义」也。「存」，犹居也。「义」者，修业之方也。「知至至之，可与几」，格物致知而诚意也。「知终终之，可与存义」，尽性至命而理于义也。「居上」「在下」，释「厉」。以下体言，则三居上画，故曰「上位」。以二体言，则三在下卦，故曰「下位」。「不骄不忧」，释「无咎」。程子曰：「君子之学如是，故知处上下之道而无骄忧，不懈而知惧，虽在危地而无咎也。」 九四曰「或跃在渊，无咎」，何谓也？上下无常，非为邪也；进退无恒，非离群也。君子进德修业，欲及时也，故无咎。 此一节释乾九四爻辞。朱子曰：「内卦以德学言，外卦以时位言。进德修业，九三备矣。此则欲其及时而进也。」澄谓：「下」释「在渊」，「进」释「跃」，「无常无恒」释「或」。或则不必其然。故下兼上言，或自渊而天也。进兼退言，或未跃则潜也。下在渊而退潜，上向天而进跃，皆未可必，故曰「无常无恒」。「非为邪，非离群」，释「无咎」。自下而上以向乎天者，非敢为干上之邪而不臣也。不退而进，以跃出乎渊者，非欲离在下之群而为君也，时当然尔。平日之进修，固欲其及时也，时之及，则其上进为无咎矣。舜自匹夫之贱，而陟帝位之贵，汤、武去诸侯之卑，而就天子之尊，时之当其可也。舜与汤、武何心焉？岂为邪？离群也哉？ 九五曰：「飞龙在天，利见大人。」何谓也？同声相应，同气相求。水流湿，火就燥。云从龙，风从虎。圣人作而万物睹。本乎天者亲上，本乎地者亲下，则各从其类也。 此一节释乾九五爻辞。鹤鸣而子和，虫雄鸣而雌应。一鸡鸣则众鸡皆鸣，同声相应也。日，火之精，而取火于日。月，水之精，而取水于月。磁石，铁之母，而可以引针，同气相求也。湿者下地，故水之流趋之；燥者乾物，故火之然就之。龙兴则致云，云从龙也。虎啸则生风，风从虎也。凡此六者，皆同类相感召。圣人与人亦同类，故作于上而万物咸睹。作，起也。物，犹人也。睹，见也。「作」字释「飞而在天」，「睹」字释「利见」。程子曰：「龙德升尊位，人之类莫不归仰。」朱子曰：「本乎天，谓动物；本乎地，谓植物。」澄案：动物首在上，亲上也。植物首在下，亲下也。先以声、气、水、火、云、风六句为比，而后言圣人作则，人利见之言。又以动植之亲上亲下，喻利见者之亲圣人。亦是谆复之，而以「各从其类」一句，总结上文九句也。或以同声为震雷巽风之声，同气为艮山兑泽之气，水流湿为坎水趋兑泽，火就燥为离火焚艮山，云从龙为坎、震，风从虎为巽、离，本乎天为震雷巽风、坎月离日之统于乾，本乎地为坎水离火、艮山兑泽之统于坤。其说陋矣。案：夫子托物广喻，非取卦象所拟也。 上九曰「亢龙有悔」，何谓也？贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。 此一节释乾上九爻辞。阳贵阴贱，「贵」，谓九为阳画也。「无位」者，阳不得阳位也。「高」，谓上居上卦之上也。阳为君，阴为民。「无民」者，纯阳无阴也。「贤人」，谓九三。「在下位」，谓在下卦也。敌体而不应上，故上无辅。「贵」，释九之为龙。「高」，释上之为「亢」。无位无民，贤人不为之辅，故「有悔」也。然亢者天时，有悔者人事。吉凶悔吝，皆生乎动。亢极之时，宜静退，不宜动进，动而后有悔也。识时善处者，虽亢而能不动，则亦不至于有悔。洪范言「用作凶」，言静而不作，亦不凶也。 「潜龙勿用」，下也。「见龙在田」，时舍也。「终日乾乾」，行事也。「或跃在渊」，自试也。「飞龙在天」，上治也。「亢龙有悔」，穷之灾也。乾元「用九」，天下治也。 此一节申乾象传意，下释「潜」，与象传同。「时舍」，谓龙之在田，犹在下位，未为时用也。「行事」，谓行其进德修业之事。「试」，犹尝试之试，自试其可跃而后跃，非必于跃也。「上」谓在天上。「治」，居上而治下也。「穷」谓亢，「灾」谓有悔。「亢而有悔」者，时至于穷而有灾也。乾元，谓以乾德居元首之尊，用九者则变为柔，以柔济刚而治天下，故天下治也。 「潜龙勿用」，阳气潜藏。「见龙在田」，天下文明。「终日乾乾」，与时偕行。「或跃在渊」，乾道乃革。「飞龙在天」，乃位乎天德。「亢龙有悔」，与时偕极。「乾元用九」，乃见天则。 此一节再申象传意。阳气潜藏于地中，象传所谓「阳在下也」。天下见其文明之德而化，象传所谓「德施普也」。行即行事之行，进德修业，时当如此，故曰「与时偕」。革，谓变革离下而升上也。有天德而位天位，故曰「位乎天德」。极者，穷而止也。三之当行，上之当止，皆因其时，故亦曰「与时偕也」。刚柔适中，天之则也。则者，理之有限节，而无过无不及者也。澄案：此前半章释一彖六爻已竟，又申绎象传至再，推演周悉，以见彖爻之辞，义理无穷，缊奥难尽。然独于乾卦如此者，盖以六十四卦之首卦，故特致详焉。以下后半章重释乾卦彖爻七节，则与第二章释坤卦彖爻七节相似。 乾元者，始而亨者也；利贞者，性情也。乾始能以美利利天下，不言所利，大矣哉！大哉乾乎！刚健中正，纯粹精也。六爻发挥，旁通情也。「时乘六龙」，以御天也；「云行雨施」，天下平也。 此一节申乾彖传意。彖传以</p><p>「大哉乾元，万物资始，乃统天。云行雨施，品物流行」五句释「元亨」。此约其言，谓「乾元」者，始物而能致品物流行之亨者也。彖传以「乾道变化，各正性命，保合太和，乃利贞」四句释「利贞」。此约其言，谓「利贞」者，其情无所不利于其性之贞也。又总「元亨利贞」，而以始言「元」，美言「亨」，利天下言「利」，不言所利言「贞」，谓乾始物之元，能以嘉美之亨为利而利天下。但言「利贞」，不言所利之为何事。盖所包甚大，非止一事之贞而己，故赞之曰「大矣哉」。其曰「大哉乾乎！刚健中正，纯粹精者」，又言「元」也。彖传言「大哉乾元」，此言其所谓「大哉」者，以其德之如是也。刚健而中正，则其刚健无过无不及而不偏。纯刚纯健，故不杂不驳矣。而中且正焉，则至精之刚健，而非其粗者也。然惟九五足以当之，乾之无九五也。曰「六爻发挥，旁通情」者，又言「贞」也。发，如发矢，挥，如挥手。旁，广也。通，达也。彖传以六位时成，言圣人之贞，此言六爻随其时位，发挥其辞，俾各得其贞者，所以广达其贞性所利之情也。曰「时乘六龙以御天」者，又言「利」也。彖传以此一句言圣人之利，而此重言之也。曰「云行雨施，天下平」者，又言「亨」也。彖传以「云行雨施」言天道之亨，以「万国咸宁」言圣人之亨。此言「天下平」者，即「万国咸宁」也。 君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。 此一节再释乾初九爻辞。「成德」，谓内有其实，外有其名，名实两全，无所亏欠。「行」，谓身之所行。「日可见」，谓显著于时，当日人皆可得而见。人不可见曰「隐」，人所可见曰「见」。君子若以成德为行，则其所行之行，皆当日人所可见者。初九之潜，隐晦于时，而未显见，则非所谓日可见之行也。所行内实有余，外名不足，而未完成，则非所谓以成德为行也。隐而未显见者，潜之象。行而未完成，是欲其弗用也，故占云「勿用」。 君子学以聚之，问以辩之，宽以居之，仁以行之。易曰：「见龙在田，利见大人。」君德也。 此一节再释乾九二爻辞。前释初九、九二，皆曰龙德，谓圣人也。再释皆曰君子，则通学知利行者而言。学，效也。有所未知，则效知者以求知之。盖理具于心，而散于事物，事物之理有一未明，则心之所具有未尽，必博学周知，俾万理皆聚而无所阙遗，故曰「学以聚之」。辩，剖决也。既聚矣，必问于先知先觉之人，以剖决其是否，故曰「问以辩之」。「宽」，犹曾子所谓「弘」，张子所谓「大心」也。「居」，谓居业之居。问既辩矣，必有弘广之量，以藏蓄其所得，故曰「宽以居之」。仁者，心德之全，天理之公也。既有以居之矣，心德浑全，存存不失，应事接物，皆践其所知，而所行无非天理之公，故曰「仁以行之」。学聚之，以知其理，仁行之，以行其事。问辩之，以审别所当行于学知之后。宽居之，以存贮所已知于仁行之先。宽之所居，即学之所聚者。仁之所行，即问之所辩者。学至于是，则为大人，虽居下位，而其德乃君德也。 九三重刚而不中，上不在天，下不在田，故乾乾因其时而惕，虽危无咎矣。 此一节再释乾九三爻辞。「九三重刚而不中」七字为句，下九四同。「重刚」，谓重乾。九三居下乾之终，接上乾之始；九四居上乾之始，接下乾之终。当重乾上下之际，故皆曰「重刚」。「不中」者，已过九二，未及九五也。「不在天」，则非上卦之中；「不在田」，则非下卦之中，所处在下之上，危地也。以其重刚，用之于学，能乾乾不懈，又因夕之时而惕若知惧，则虽处危地，而无咎也。 九四重刚而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故无咎。 此一节再释乾九四爻辞。六画之卦，三与四皆人位也。然九三下履二地，乃人所常居之处；九四上戴五天，在人头上空虚之间，故曰「中不在人，不在天，不在田」。又不在人，则无依倚停驻之所，故疑而未决。可以至天，则自渊跃出，经由乎四，而遂上于天。若未可至天，则且当在渊而潜，未可望四而跃也。盖四之位可经过，而非可停驻，必审其可跃而后跃，乃无咎也。 夫大人者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。先天而天弗违，后天而奉天时。天且弗违，而况于人乎？况于鬼神乎？ 此一节再释乾九五爻辞。九二、九五皆大人。前释九二盛言其德，释九五则不言其德，但言人之利见。至此再释，乃言九五大人之德，与前所释互相备也。夫天，专言之则道也。此虽兼地言之，而曰天地，然与专言天之一字者同。盖以其主宰之理而言，非指轻清之气为天，重浊之质为地也。日月、四时、鬼神，皆天地之气所为。气之有象而照临者为日月，气之循序而运行者为四时，气之往来屈伸而生成万物者为鬼神。命名虽殊，其实一也。其所以明、所以序，所以能吉能凶，皆天地之理主宰之。天地以理言，故曰德。日月、四时、鬼神以气言，故曰明、曰序、曰吉凶也。程子曰：「天地者，道也。鬼神者，造化之迹也。大人与天地、日月、四时、鬼神合者，合乎道也。」朱子曰：「日月、四时、鬼神，是指形而下者。人与天地、鬼神本无二理，特蔽于有我之私，是以梏于形体而不能相通。大人无私，与道为体，曾何彼此先后之可言哉？先天弗违，谓意之所为，默与道合。后天奉时，谓知理如是，奉而行之。澄谓：人弗能违，故圣人作而皆利见之也。」 「亢」之为言也，知进而不知退，知存而不知亡，知得而不知丧。知进退存亡而不失其正者，其唯圣人乎！ 此一节再释乾上九爻辞。进退言人事，存亡得丧言时命。得与存之时，进之时也；丧与亡之时，退之时也。但知其得与存而进，不知其丧与亡而退，所以亢也。知进之有退，存之有亡，得之有丧，而处之至当，各得其理之正，则可以不亢而无丧亡之祸矣。故惟圣人能之。「知进退存亡」下不再言得丧者，省文。传七之一章，凡七百五十六字，释乾卦彖爻之辞。旧本「何谓也」六句之下，各有「子曰共」十二字，盖后人所加。「德博而化」之下，有「易曰：见龙在田，利见大人，君德也」十三字，盖下文重出。「情性也」作「性情」，今依郑本。「知得而不知丧」之下，有「其唯圣人乎」五字，亦下文重出，安定胡氏以为羡文。长，知两切，下同。乐音洛。见龙、未见，并贤遍切。庸行、为行之行，并下孟切。几，平声。离，力智切。舍音舍。施，时至切。夫，音扶。先天，悉荐切。丧，昔浪切。注身隐而不见曰见。显见，并贤遍切。子和，苻卧切。乾物，音于。审别，彼列切。夫天，音扶，省文，所梗切。</p><p>坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎，承天而时行。 此一节申坤彖传意。彖传言至哉坤元，此言其所谓「至哉」者，以其柔静之至而又刚方也。坤体中含乾阳，如人肺藏之藏气，故曰至柔；然其气几一动而辟之时，乾阳之气直上而出，莫能御之，故曰「刚」，刚即六二爻辞所谓「直」也。乾运转不已，而坤体𬯎然不动，故曰「至静」；然其生物之德，普徧四周，无处欠缺，故曰「方」，「方」即六二爻辞所谓「方」也。坤之「元」，六二也。「乾」之九五，不徒刚健，而能中正，故为「乾元」之大；坤之六二，不徒柔静，而能刚方，故为「坤元」之至。彖传言「后顺得常」，此言后则顺而得所主，是有坤道之常也。彖传言「含弘光大」，此言静翕之时，含万物生意于中，动辟则化生万物而光辉也。彖传言「乃顺承天」，此言坤道之顺承天之健，而随天之时以行也。 积善之家，必有余庆；积不善之家，必有余殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辩之不早辩也。易曰「履霜坚冰至」，盖言慎也。 此一节释坤初六爻辞。为善则有福庆，为不善则有祸殃，必然之理也。然皆自小而积，以至于大。小善积而为大善，则福庆亦大而为余庆；小不善积而为大不善，则祸殃亦大而为余殃。程子曰：家之所积者善，则福庆及于子孙；所积不善，则灾殃流于后世。其大至于弑逆之祸，皆因积累而至，非朝夕所能成也。朝与夕，渐不可长，小积成大，辩之于早，使民下之恶无由而成，乃如履冰之戒也。澄谓：履霜于纯坤将用事之初，知阴之始凝而渐盛，坚冰必至于纯坤既用事之后也。不善之积，必为大祸殃，亦如此。防几杜渐者，当慎之于初，不可坐待其由渐而积，以至于极也。 直其正也，方其义也。君子敬以直内，义以方外，敬义立而德不孤。「直、方大，不习无不利」，则不疑其所行也。 此一节释坤六二爻辞。象辞之所谓直者，言坤体之上下也；方者，言坤体之东西南北也。此就人言之，则直者言其心体之正也，方者言其制事之义也。正之存于中，如物之直而不斜倚；义之应于外，如物之方而不亏缺也。程子曰：君子主敬以直其内，守义以方其外。敬立而内直，义形而外方。义形于外，非在外也。敬义既立，其德盛矣，德不孤也。无所用而不周，无所施而不利，孰为疑乎？朱子曰：「不孤，言大也。」澄谓：两者对峙之谓立，有敬、直而无义、方，有义乃方而无敬、直则独而不两，孤而不可以为大。「敬义两立，德不孤」，释直方然后大也。「不疑其所行」，释「无不利」。 阴虽有美，含之以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成，而代有终也。 此一节释坤六三爻辞。项氏曰：「阴虽有美，含之绝句，以含之连下文读者，非。」澄谓：阳明阴晦，阴虽有章明之美，亦含藏于内而不显露。阴者为臣之道也。故臣以之而从王事者，不敢居其完全之功。盖地道但得天道之半，妻道臣道皆然。无成者，无全功也。天始物而地代，天生物以终天之施。代，犹继也，继阳之后而终之也。不有其始，但有其终，阙其半而不完全，故曰无成。夫倡于前，妻随于后，君令于始，臣行于终，是亦无成而代有终也。 天地变化，草木蕃。天地闭，贤人隐。易曰：括囊，无咎无誉。盖言慎也。 此一节释坤六四爻辞。上卦为天，下卦为地，上下体不相应，有天地否隔之象。四居上下体之际，故发此义。四变为刚，则如否卦之初六、九四，亦天地不交也。变化，谓天地交而变化生万物，此以小气数言一岁之春夏也。闭，谓天地不交而闭塞不相通，此以大气数言一运之秋冬也。春夏天地变化而草木蕃，秋冬天地闭塞而草木瘁，岁气然也。盛世君臣和同而贤人出，衰世君臣乖隔而贤人隐，运数然也。各言其一者，互相备也。或云，皆言运数也，特其盛衰治乱，有似一岁之春夏秋冬尔。「草木蕃」者，召南所谓「朝廷既治，庶类蕃殖」也。「贤人隐」，洪范所谓「百谷不成，俊民用微」也。项氏曰：草禾且蕃，况于人乎？言「盛」者，要其终也。贤人隐，则物从之矣。言衰者，记其始也。程子曰：「天地交感，则变化万物，草木蕃盛。君臣相际而道亨。天地闭隔，则万物不𨔵。君臣道绝，贤者隐遁。四于闭隔之时，括囊晦藏，则虽无令誉，可得无咎。言当慎自守也。」 君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。 此一节释坤六五爻辞。爻辞曰「黄裳」，言以中央之色，为下体之饰，以譬君子之德，美在中心，而形见于身为事业也。「黄中」，黄色在中也。「通」，达也。「理」，身之肤腠也。东方青，南方赤，西方白，北方黑，皆偏位，唯中央黄色为正位也。「居体」，居下体也。黄在中而外达于身之肤腠者，以正位之色为裳，而居于身之下体也。「美在其中」，谓「黄中正位」。「畅于四肢」，谓「通理居体」。君子之发于事业，以饰其身，由其中心德美之至也。故自中心而发为饰身之事业，亦如在中黄色之美，而为饰身之裳也。「裳」之所蔽者二足，而言「四支」者，立言之法如此也。项氏曰：「黄中正位，美在其中，属黄字。」通理居体，畅于四支，属裳字。 阴疑于阳必战，为其嫌于无阳也，故称「龙」焉。犹未离其类也，故称「血」焉。夫玄黄者，天地之杂也，天玄而地黄。 此一节释坤上六爻辞。「疑」，如礼记「疑于臣」、「疑于君」、「疑女于夫子」之「疑」，谓与之并也。六阴同类，同类之中，一阴独疑于阳，五阴其肯从之乎？必与之战矣。「战」者，五真阴敌一伪阳也。「坤」本无阳，上六变而为阳，若不称「龙」，则不见其已变为阳也。虽已变为阳，而本质则阴，故其遭伤也称血，以见其虽变为阳，而未脱离阴类也。「血」者，阴之伤，而上六之阴，异乎真阴，故其血玄而黄，若真阴，则有黄无玄也。盖「玄」者，新变为阳之色；「黄」者，旧质为阴之色也。玄黄之血相杂，有天阳之色，又有地阴之色，以见其非臣亦非君也。项氏曰：「玄黄」者，上下无别，所谓杂也。曰「疑于阳」，曰「嫌于无阳」，曰「犹未离其类」，曰「天地之杂」，皆言阴之似阳，臣之似君。楚公子围之美矣君哉也，然终以野死，则亦何利哉！</p><p>传七之二章，凡二百五十六字，释坤卦彖爻之辞。盖言慎也旧本「慎」作「顺」。朱子曰：古字「顺」、「慎」通用，此当作慎，言当辩之于微也。今从之。为其云伪切。离力智切。夫音扶。注渐不可长知两切。要一遥切。形见见其并贤遍切。无别彼列切。 危者，安其位者也；亡者，保其存者也；乱者，有其治者也。是故君子安而不忘危，存而不忘亡，治而不忘乱，是以身安而国家可保也。易曰：「其亡其亡，繋于苞桑。」 此一节释否九五爻辞。自处于危者，乃自安其位之道也。凛乎若将亡将乱者，乃所以常保其存，常有其治也。九五否将休矣，而不忘戒惧如此。盖于安、存治之时，而能不忘危、亡乱之祸，是以身之位得以安，而国家可保其久存长治也。爻辞亡字，失物之亡，传所谓亡，亡国亡家之亡。案：繋辞传明中古圣人忧患之深意，而蔽以一言曰「其辞危」。此传于乾坤二卦外释诸爻之辞，而首及「危」之一字，夫子之意，亦文王、周公之意与？ 同人，先号啕而后笑。君子之道，或出或处，或默或语。二人同心，其利断金。同心之言，其臭如兰。 此一节释同人九五爻辞。君子之道，不皆同也。以身之行，则出处或不同；以口之言，则默语或不同。然一人之心既同，则言行不必同，而无能间其同者。故同心者之行，譬如至利之器，可断至坚之金，无物能梗碍之也。同心者之言，譬如幽生之兰，自有远闻之香，无物能障隔之也。九五、六二，其心同一中正，其先暂为三四所间而号啕，其后终得相遇而笑。盖其心之同，非三四所能梗碍障隔也。 易曰：「自天祐之，吉无不利。」祐者，助也。天之所助者，顺也。人之所助者，信也。履信思乎顺，又以尚贤也。是以「自天祐之，吉无不利」也。 此一节释大有上九爻辞。「天」，谓上九。「顺」，谓六五得「坤」之柔中。「人」，谓九四。「信」，谓九四刚实。六五履刚实之四，所履者信也。五为心位，能思而得坤中之顺，以顺上九之阳，「思乎顺」也。上九阳刚为贤，而六五尊之在已上，所尚者贤也。六五有履信思顺尚贤之德，不但九四之人助之，而上九之天亦助之，是自天而「祐之」也。宜其占之「吉」，而且「无不利」也。 「劳谦」，君子有终，吉。劳而不伐，有功而不德，厚之至也。语以其功下人者也。德言盛，礼言恭。谦也者，致恭以存其位者也。 此一节释谦九三爻辞。「劳」，谓竭其力。「劳」者，有功之本。「有功」者，劳之效。「厚之至」，谓非气量浅薄者所能也。「德言盛」，释「劳」字。「礼言恭」，释「谦」字。「言」，助辞，如说卦传之「说言」、「成言」，诗之「薄言」、「驾言」也。致恭，谓劳而能谦。「存其位」，谓有终而吉。程子曰：「有劳而不自矜伐，有功而不自以为德，是其德弘厚之至也。」言以其功劳而自谦以下于人也。以其德则至盛，以其自处之礼则至恭，所谓谦也。「存」，守也。致其恭巽以守其位，故高而不危，满而不溢，是以能「终吉」也。夫君子履谦，乃其常行，非谓保其位而为之也。言能致恭，所以能存其位。如言为善有令名，君子岂为令名而为善也哉？亦言有令名者，为善之故也。 知几其神乎！君子上交不谄，下交不渎，其知几乎？几者，动之微，吉凶之先见者也。君子见几而作，不俟终日。易曰：「介于石，不终日，贞吉。」介如石焉，宁用终日？断可识矣。君子知微知彰，知柔知刚，万夫之望。 此一节释豫六二爻辞。「知几」，谓知之于其事未显著之先，所以为神也。「君子」谓六二，有中正之德也。「上」谓六三，「下」谓初六。六二上比三，下比初。然六二中正，初三柔邪，虽比近而不同，情交而不谄不渎者也。盖九四以不中不正为豫乐之主，而三比之，初应之。初、三者，四之党与也。二中正自守，不肯阿附四之权势，故虽四之党与，亦不与之深交者，杜绝阿附之事于几微之时也。故曰：「其知几乎？」几者，动之始，其端眇芒，要终而论。其后或谓六二之贞吉，或谓初、三之凶悔，皆以阿附不阿附而判，所当辨别于始也。其始吉凶虽未显著，而其端可见矣，故曰「先见者也」。「作」如「作者七人」之作，谓起去而退处也。穆生得免申白之祸者，能见几而作也。刘、柳竟陷伾文之党者，不能见几而作也。二介于三，虽未措足于四之刚，而已知其如石矣。谓三为互坎之下画，与四同体也。「宁用终日」，谓虽与三比，而不久留于三，速退处二以自守，其见早也。几动之在先者虽微，而吉凶之先见者则彰。六三之为比者虽柔，而其前之为四者则刚。知所动之微，而已知其后之必彰矣，不待见吉凶而始知其彰也。知所比之柔，而已知其前之有刚矣，不待近九四而始知其刚也。非知几，其孰能之？程子曰：「见事之几微者，其见必早。如交于上以恭巽，过则为谄；交于下以和说，过则为渎。君子见于几微，故不至于过焉。」几者，始动之微，吉凶之端，可先见而未著者也。明哲见几而动，岂俟终日断别也，其判别可见矣。微与彰、柔与刚相对，君子见微则知彰，见柔则知刚，知几如是，众所仰也，故曰「万夫之望」。 小人不耻不仁，不畏不义，不见利不劝，不威不惩。小惩而大诫，此小人之福也。易曰：「屦校灭趾，无咎。」此之谓也。 此一节释噬嗑初九爻辞。小人愚下，不知不仁之事为可耻，不知不义之事为可畏，故不诱以利，则不能劝其为善；不慑以威，则不能惩其为恶。噬嗑之初，听讼之初也。初九为初犯之人，逮捕方至，情实未明，拘以足械，防其走逸而待讯。及其既讯，则无可罪而得释免。其小人一受小威之惩，因此知耻知畏，以受大刑为戒，而终身不敢为恶，则此一小惩，反为小人之福。所以暂屦灭趾之校，而卒无再犯之咎也。 善不积不足以成名，恶不积不足以灭身。小人以小善为无益而弗为也，以小恶为无伤而弗去也，故恶积而不可掩，罪大而不可解。易曰：「何校灭耳，凶。」 此一节释噬嗑上九爻辞。为善者必有利益，自小善积为大善，而后成名；为恶者必有害伤，自小恶积为大恶，而后灭身。小人无知，以人之尝为小善而未成名，则以为无益而弗之为；以已之尝为小恶而未灭身，则以为无伤而弗之去。于是长恶不悛，犯罪至极。噬嗑之终，听讼之终也。上为怗终之人，狱辞既具，罪名已定，锢以首械，表其罪犯而待刑。此积成大恶而不复可以揜覆，犯至大罪而不复可以解脱者，所以既荷灭耳之校，而卒受刑诛之凶也。传文「灭身」之灭，灭，死也。经文「灭耳」之灭，灭，没也。 颜氏之子，其殆庶几乎！有不善未尝不知，知之未尝复行也。易曰：「不远复，无祇悔，元吉。」 此一节释复初九爻辞。项氏曰：殆，将也。庶几近辞。朱子曰：言近道也。程子曰：颜子无形显之过，夫子谓其庶几，未能不勉而中，所欲不逾矩，是有过也。然其明而刚，故一有不善，未尝不知；既知，未尝不遽改，乃不远复也。过既未形而改，何悔之有？复者，阳反来复也。阳，君子之道，故复为反善之义。初阳来复，处卦之初，复之最先，不远而复者也。失而后有复，唯失之不远而复，则不至于悔也。 初六，藉用白茅，无咎。苟错诸地而可矣，藉之用茅，何咎之有？慎之至也。夫茅之为物薄，而用可重也。慎斯术也以往，其无所失矣。 此一节释大过初六爻辞。苟，犹若也。慎，谨敬也。薄，犹轻也。术，犹道也。大过之时，四阳过盛，初六以卑弱之阴在下，承藉四阳，其谨敬亦过甚。譬之祭物，若但措之于地亦可矣，而必藉之以茅，谨敬之至也。夫茅之为物虽轻，非可重者，而用之以藉祭物，则其用可重也。人能谨敬于此所行之道，则凡事皆无所失矣。蔡氏曰：「天下之事，过则有失，唯过于慎，则无所失，故无咎。」传七之三章，凡四百四十九字，释上经八卦九爻之辞。此章并第四章，旧木错简在繋辞上下传二篇中。盖夫子既释乾、坤二卦，其余六十二卦三百七十二爻之辞不能徧释，故上经释九爻，下经释九爻，以发其例，而他爻可以类推，是为文言传。后人以所释乾、坤二卦之辞附入本卦，于是所释上下经十六卦爻辞十八节不能成篇，遂散入繋辞传，离为三处，颠倒紊乱特甚。如释大有爻辞内十字，断简重出至再。释乾彖爻既附于乾卦，而释上九爻辞一节亦复重出，杂于十八节之间，但少「上九曰何谓也」六字，今悉更定。释否九五、豫六二、噬嗑初九、复初九四处，并增「子曰」字发端。释同人九五、大有上九、谦九三、大过初九四处，并增「子曰」字，在所引经文之下。唯释噬嗑上九一节未增，其所增者今删去。吉凶之先见旧本无凶字。号平声。断金东管切。先见陆贤遍切。今读如字。断可东乱切。校胡校切。弗去羌吕切。何河可切。复行符后切。藉疾夜切。错初故切。夫音扶。注意与音余。之行，言行、常行，并下孟切。间居限切。远闻音问。说言音曰。夫君子音扶。非为、岂为，并云伪切。要一遥切。辨别、断别、判别，并彼列切。和易以豉切。弗之去羌召切。长恶知两切。悛七全切。不复符后切。覆孚后切。荷河可切。而中贞仲切。</p><p>易曰：「憧憧往来，朋从尔思，天下何思何虑？天下同归而殊涂，一致而百虑，天下何思何虑？日往则月来，月往则日来，日月相推而明生焉。寒往则暑来，暑往则寒来，寒暑相推而岁成焉。往者屈也，来者信也，屈信相感而利生焉。尺蠖之屈，以求信也；龙蛇之蛰，以存身也；精义入神，以致用也；利用安身，以崇德也。过此以往，未之或知也。穷神知化，德之盛也。」 此一节释咸九四爻辞。九四变刚为柔，舍其正应之感，其意憧憧不定，昵于近比之感。四往感五，五因四之感而来感四，私意相感，非此心正理之感也。夫子先言人心定应寂然之感，以明九四憧憧之非；次言天道往来自然之感，以明四、五往来之非也。思者，心之用；虑者，谋度其事也。归者，所归之舍；致者，所至之地。皆谓心也。心体虚灵，如止水明镜，未与物接，寂然不动，何思之有？既与物接，应之各有定理，何虑之有？理之在心者同，因事之不同，而所行之涂各殊；理之在心者一，因事之不一，而所发之虑有百。涂虽殊，虑虽百，而应事之理则同而一也。故定心应事，动而无动，则亦何思何虑之有？此人心定应寂然之感也。若九四之「憧憧」，则岂如是乎？因日之往，而有月之来，因月之往，而有日之来，二曜相推以相继，则明生而不匮。因寒之往而有暑之来，因暑之往而有寒之来，二气相推以相代，则岁成而不缺。往者之屈感来者之信，来者之信又感往者之屈，而有明生岁成之利，此天地往来自然之感也。若四、五之往来，则岂如是乎？夫子既以「屈信」二字释往来之相感，复以物理之屈信、圣学之屈信言之而广其意。尺蠖不屈，则其行不能伸，既伸而再行，则又屈也。龙蛇不蛰，则其来岁之身不能奋，既奋于来岁，则又蛰也。此物理之屈伸相感也。义理精明，则应物有定，而神不外驰。入者无出，内之屈也，而乃所以致极其外之用，屈之感信也。日用宜利，则每事曲当，而身之所处，随寓而安，外之信也，而乃所以增崇其内之德，信之感屈也。此圣学之屈信相感也。因言圣学之交相养、互相发，工力至此，则蔑以加矣。过此以往者，为更进而前也。未之或知者，谓非人之所能知也。朱子曰：「自是以上，亦无所用其力矣。至于穷神知化，乃德盛仁熟而自致尔。」澄谓：「穷神者，究竟至此，则心之所存，与天地之心为一。知化者，了悟至此，则身之所行，与天地之事如一。」 作易者，其知盗乎？易曰：「负且乘，致寇至。」负也者，小人之事也；乘也者，君子之器也。小人而乘君子之器，盗思夺之矣。上慢下暴，盗思伐之矣。慢藏诲盗，冶容诲淫。易曰：负且乘，致寇至，盗之招也。 此一节释解六三爻辞。作易者，作爻辞之圣人也。坎体之阴画为盗，即爻辞所谓寇也。思，语辞。六三负四乘二，九四为互坎中画之君，以其互坎下画之民，据处六三之位而夺之。六三在四之下，而无顺戴之恭，慢其上也；在二之上，而有凌乘之僭，暴其下也。故声其暴慢之罪而伐之。「慢藏诲盗，冶容诲淫」八字，盖旧有此语，而引之以证六三之招盗。然所招之盗，能夺六三非据之位，能伐六三可罪之恶，其夺之也当，其伐之也有名，亦异乎发藏取货之盗矣。而谓之寇者，凡可以已而擅兴以夺人伐人者，其事虽当，虽有名，亦寇盗也。程于曰：作易者其知盗乎？谓盗者乘衅而至，苟无衅隙，盗安能犯负者而乘，非所安也，故盗乘衅而夺之。满假而慢上暴下，盗则乘其过恶而伐之。伐者，声其罪也。货财而轻慢其藏，是教盗使取之也。女子而天冶其容，是教淫者使暴之也。小人而乘君子之器，是招盗使夺之也。 易曰：公用射隼于高墉之上，获之，无不利。隼者，禽也。弓矢者，器也。射之者，人也。君子藏器于身，待时而动，何不利之有？动而不括，是以出而有获，语成器而动者也。 此一节释解上六爻辞。「翰飞之戾天」者，隼也。三四五互坎为弓，上六变，则上体成离为矢。九四，上卦之君。爻辞所谓公者，射之之人也。君子，即九四也。有弓矢之器在身，必得时至上六而后动者，盖解以二阳解四阴之难，初、三、五之三阴，已为九二所解矣。上六所居最远，九二之力，不能及之，九四之力，亦止可以及三阴。唯上六一阴之难未解，待至上六变柔而刚，则成离矢之镞，而九四之矢镞，能及上六戾天之隼矣。故九四之动，无所结碍，一出而能有获者，待至器成之时而动故也。上六未变，则九四之弓虽具，而矢犹未具，是弓矢二器，未能完全也。上六既变为离，则弓具矢具，而器成矣。括，结碍也。成，完全也。程子曰：「行一身至于天下之事，苟无其器，与不以时而动，小则括塞，大则丧败。自古喜有为而无成功，或颠覆者，皆由是也。」 天地𬘡缊，万物化醇。男女构精，万物化生。易曰：「三人行，则损一人；一人行，则得其友。」言致一也。 此一节释损六三爻辞。凡物之相合，可二而不可三。盖以一合一，则其情专；以一合二，则其情分。故三人行则有余，而当损其一；一人行则无对，而当益其一。然后二人相与，其情专致于一而不二乎他也。夫子因以天地之阴阳、男女之牝牡言之。𬘡缊者，气之交也。构精者，形之交也。天地之二气交，故物之以气化者，其气𬪩厚而能醇。男女之二形交，故物之以形化者，其精凝聚而能生。此气形之相皆交以二，与三人损一、一人得友之义合。盖二者其理同，言其以一合一，故能致一而不二也。 君子安其身而后动，易其心而后语，定其交而后求。君子修此三者，故全也。危以动，则民不兴也。惧以语，则民不应也。无交而求，则民不与也。莫之与，则伤之者至矣。易曰：「莫益之，或击之，立心勿恒，凶。」 此节释益上九爻辞。「安其身」，谓循理则身康安。「动」，谓由已及物，以变动其民也。「易其心」，谓阙志则心和易。「语」，谓由中达外，以告语其民也。「定」者，前定。「交」者，下交。「于民」，谓先施于民以固结之。「求」犹责也，谓责其爱戴归向也。「修」，谓安身、易心、定交三者皆无缺全，谓民兴起而与之也。欲胜理则身多危，而不足以率人，故动之而民不兴喜。气胜志则心多惧，而不足以感人，故语之而民不应合。「无交而求，则民弗与」者，无以固结其民于先，而求其报上，则民不助之也。「益」者，以上益下。上九之君，当益六三之民，今不能利益其民，乃或有时而击害其民，是上之先施者，无以交结其民，而求民之报上，则民之所报，亦如君之所施者矣。君莫益其民，而民亦莫与其君；君或击其民，而民亦或伤其君。民莫之与，而伤之者至，此曾子所谓「出乎尔者反乎尔」，孟子所谓「民今而后能反之」者也。上九无益民之心，而或有害民之心，当速改变，此心不可恒也。故爻辞戒之曰：「立心勿恒。」「莫益之，或击之」之义，尤足示训戒者，故夫子发明君民施报之理如此。盖因经文「凶」字而生出此意也。释爻辞，但取「定其交」一句，因泛及「安其身」、「易其心」二句耳。 易曰：「困于石，据于蒺藜，入于其宫，不见其妻，凶。」非所困而困焉，名必辱；非所据而据焉，身必危。既辱且危，死其将至，妻其可得见邪？ 此一节释困六三爻辞。非所困，非所据，谓六三不当乘九二也。六三以不中不正之柔，乘九二刚中之上，其周官所谓罢民之有过恶者与？「困于石」者，过恶犹轻，而坐于嘉石者也。或三日，或五日，或七日，或九日，或旬有三日而免。未丽于法，耻之而已矣，故曰名辱。「据于蒺藜」者，过恶加重，而置于丛棘者也。入圜土，收教之，能改者，或一年，或二年，或三年而舍，不能改而出圜土者杀。已丽于法，刑罚将及矣，故曰身危。先困辱于坐石，后据危于蒺藜，由辱而至危，非能改其过恶者，必至于死，故曰「死其将至」。「其」者，将然之辞。虽暂还家，而妻已离异，故曰妻其可得见邪。详见经注及象传注。 德薄而位尊，知小而谋大，力小而任重，鲜不及矣。易曰：「鼎折足，覆公𫗧，其刑剭，凶。」言不胜其任也。 此一节释鼎九四爻辞。九四阳画离体，而与初正应。阳刚有德者也，而居柔，则其德薄矣。上体而近君，则其位尊也。离明有知者也，而未中，则其知小矣。三牲而大烹，则其谋大也。德知在已，力资乎人者也。初六正应而柔弱，则其力小矣。鼎重器，而有公𫗧实之，则其任重也。有大德者，职位可以尊，德薄则不足以称其位矣。有大知者，图谋可以大，知小则不足以周其谋矣。有大功者，负任可以重，力小则不足以胜其任矣。德不称其位，知不周其谋，力不胜其任，则鲜有不及祸者。程子曰：「四下应初，初阴柔不胜任，犹鼎之折足，覆公上之𫗧也。」澄案：释爻辞取力小而任重之义，因及前二句尔。 不出户庭，无咎。乱之所生也，则言语以为阶。君不密则失臣，臣不密则失身，几事不密则害成，是以君子慎密而不出也。 此一节释节初九爻辞。初九当节之初，慎守其正而不轻动，犹人在内而不轻出至户外之庭。夫子以为人之慎言而不轻出诸口者，亦当如是。「阶」，犹云所由也。祸乱之所生，每由于言语。君不慎密其言，则臣或受祸，而因此遂失其臣；臣不慎密其言，则身或受祸，而因此遂失其身。几密之事，未彰于外，不可使人知者，若不慎密其言，则或至漏泄，而因此遂成患害。是以君子慎密其言而不敢轻出者，节之也。此爻辞所象慎动之节，而夫子以发言之辞释之。程子曰：「在其所节，惟言与行。节于言，则行可知，言当在先也。」 鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。君子居其室，出其言善，则千里之外应之，况其迩者乎？居其室，出其言不善，则千里之外违之，况其迩者乎？言出乎身，加乎民；行发乎迩，见乎远。言行，君子之枢机。枢机之发，荣辱之主也。言行，君子之所以动天地也，可不慎乎！ 此一节释中孚九三爻辞。「鸣鹤」，谓九。「在阴」，谓二。君子居室，犹鹤之在阴也。出言之善，犹鹤之鸣也。「千里之外应之」，谓九二远得九五之应也。「况其迩者乎」，谓九二近得六三之和也。若其出言之不善，则反是，远不孚而近亦不孚矣，何以有九五之应、六三之和哉？「言出乎身，加乎民」，释「鸣鹤在阴，其子和之」二句。言者，九二之鸣也。「出乎身」，释「鹤在阴」，谓其言肇起于二也。二刚，画鹤之身也。「加乎民」，释「子和之」，谓其言及于三也。三柔，画二之民也。「行发乎迩，见乎远。」释「我有好爵，吾与尔靡之」二句。行者，九五之好爵也。「发乎迩」，释「我有」，谓其行先达于四也。四近比，故曰「迩」也。「见乎远」，释「尔靡之」，谓其行形著于二也。二应位，故曰「远」也。二、五以中实相感应，故九二近得六三同体之孚，而远得九五同德之孚。九五近得六四同体之孚，而远得九二同德之孚也。枢，门枨。机，弩牙也。枢一发而扉动，机一发而矢去。言行之发，有善不善，而远近之应与违各异。应主荣，违主辱，亦犹扉动而有开阖，矢去而有中否也。言行不唯可以动人，而又可以动天地。君子岂可不慎其言行，而出善言善行乎？九二之言，近感三而远感五，诚之动人而上动乎天也。九五之行，近感四而远感二，诚之动人而下动乎地也。天地非有二，地亦天也，以卦位上下分属则如此尔。</p><p>传七之四章，九六百一十九字，释下经八卦九爻之辞。旧本释咸九四、解上六、困六三、节初九、中孚九二五处，并增「子曰」字，在所引经之下，释解六三、益上九、鼎九四三处，并增「子曰」字。发端唯释损六三一节未增，其所增者，今删去。则民不兴也，「兴」作「与」。今案：「与」字与下文重「兴」字，则「兴」应韵叶。死其将至，「其」作「期」，今从陆氏释文本及东莱吕氏音训所定。其刑剭，俗本作「形渥」，说见经注。乘平声。信音伸，并同。藏，木浪切。射，食亦切。易其心，以豉切。知小音智。鲜，仙展切。折，之设切。胜音升。子和，胡卧切。靡，蒙池切。见，贤遍切。行，下孟切。后同注。舍其音舍。近，比皮二切。谋度，待洛切。难，奴旦切。丧败去声。施报，时至切。罢民音皮。称，充证切。为比，云伪切。 易纂言卷九</p>',10)])])}const h=e(n,[["render",r]]);export{f as __pageData,h as default};
